WITH scored AS (SELECT id, email, country, segment, MIN(credit_limit) OVER (PARTITION BY segment ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_credit_limit, AVG(credit_limit) OVER (PARTITION BY segment ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_credit_limit, MAX(credit_limit) OVER (PARTITION BY segment ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_credit_limit, COUNT(credit_limit) OVER (PARTITION BY segment ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_credit_limit, ROUND(age / SUM(age) OVER (PARTITION BY segment), 4) AS age_share FROM customers WHERE signup_date <= '2025-07-01') SELECT id, email, running_min_credit_limit, running_avg_credit_limit, age_share FROM scored ORDER BY id NULLS LAST LIMIT 5;
